# ---- poker_core.py ----
RANKS = "23456789TJQKA"

SUITS = "cdhs"

_SUIT_ALIASES = {"♣": "c", "♦": "d", "♥": "h", "♠": "s"}

MONSTER, STRONG, MEDIUM, STRONG_DRAW, DRAW, WEAK = (
    "MONSTER", "STRONG", "MEDIUM", "STRONG_DRAW", "DRAW", "WEAK")

def parse_card(s):
    if isinstance(s, int):
        return s
    s = s.strip().replace("︎", "").replace("️", "")
    if s.startswith("10"):
        s = "T" + s[2:]
    suit = _SUIT_ALIASES.get(s[1], s[1].lower())
    return RANKS.index(s[0].upper()) * 4 + SUITS.index(suit)

def parse_cards(cards):
    """Accepts ["Ah", "Kd"], "Ah Kd", "AhKd", "A♥ K♦" or ints."""
    if not cards:
        return []
    if isinstance(cards, str):
        s = cards.replace("︎", "").replace("️", "").replace("10", "T")
        s = "".join(ch for ch in s if ch not in " ,[]'\"")
        return [parse_card(s[i:i + 2]) for i in range(0, len(s), 2)]
    return [parse_card(c) for c in cards]

def card_str(c):
    return RANKS[c >> 2] + SUITS[c & 3]

def hand_class(c1, c2):
    """Two cards -> canonical class like 'AKs', 'T9o', '77'."""
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2:
        r1, r2 = r2, r1
    if r1 == r2:
        return RANKS[r1] * 2
    return RANKS[r1] + RANKS[r2] + ("s" if (c1 & 3) == (c2 & 3) else "o")

ALL_CLASSES = frozenset(hand_class(a, b) for a in range(52) for b in range(52) if a != b)

def _expand(hi, lo_from, lo_to, suffix):
    out = set()
    for lo in range(lo_from, lo_to + 1):
        base = RANKS[hi] + RANKS[lo]
        out.update([base + "s", base + "o"] if suffix == "" else [base + suffix])
    return out

@lru_cache(maxsize=None)
def parse_range(text):
    """Range string -> frozenset of hand classes. See config.py for syntax."""
    out = set()
    for tok in text.replace(";", ",").split(","):
        tok = tok.strip()
        if not tok:
            continue
        if tok in ("*", "any", "random"):
            return ALL_CLASSES
        t = tok[0].upper() + tok[1].upper() + tok[2:].lower()
        try:
            if "-" in t:
                a, b = (x.strip() for x in t.split("-"))
                a = a[0].upper() + a[1].upper() + a[2:]
                b = b[0].upper() + b[1].upper() + b[2:]
                ra, rb = RANKS.index(a[0]), RANKS.index(b[0])
                if a[0] == a[1]:  # pair span "77-44"
                    lo, hi = sorted((ra, RANKS.index(b[1])))
                    out.update(RANKS[r] * 2 for r in range(lo, hi + 1))
                else:  # "A5s-A2s"
                    assert ra == rb, "range span must share the top card"
                    k1, k2 = sorted((RANKS.index(a[1]), RANKS.index(b[1])))
                    out |= _expand(ra, k1, k2, a[2:3])
                continue
            plus = t.endswith("+")
            t = t.rstrip("+")
            r1, r2 = RANKS.index(t[0]), RANKS.index(t[1])
            suffix = t[2:3]
            if r1 == r2:
                out.update(RANKS[r] * 2 for r in range(r1, 13 if plus else r1 + 1))
            else:
                hi, lo = max(r1, r2), min(r1, r2)
                out |= _expand(hi, lo, hi - 1 if plus else lo, suffix)
        except (ValueError, IndexError, AssertionError) as e:
            raise ValueError(f"Bad range token {tok!r}: {e}") from None
    return frozenset(out)

def range_pct(rng):
    """Fraction of all 1326 combos covered by a parsed range (for sanity checks)."""
    combos = sum(6 if len(h) == 2 else 4 if h[2] == "s" else 12 for h in rng)
    return combos / 1326

def _straight_high(ranks):
    for hi in range(12, 3, -1):
        if hi in ranks and hi - 1 in ranks and hi - 2 in ranks and hi - 3 in ranks and hi - 4 in ranks:
            return hi
    if 12 in ranks and 0 in ranks and 1 in ranks and 2 in ranks and 3 in ranks:
        return 3
    return -1

def hand_rank(cards):
    """Best hand from any number of cards -> comparable tuple (bigger is better).
    Category: 8 SF, 7 quads, 6 full house, 5 flush, 4 straight, 3 trips, 2 two pair, 1 pair, 0 high."""
    rc = [0] * 13
    sc = [0] * 4
    for c in cards:
        rc[c >> 2] += 1
        sc[c & 3] += 1
    flush = None
    for s in range(4):
        if sc[s] >= 5:
            fr = sorted({c >> 2 for c in cards if c & 3 == s}, reverse=True)
            sf = _straight_high(set(fr))
            if sf >= 0:
                return (8, sf)
            flush = fr
            break
    desc = [r for r in range(12, -1, -1) if rc[r]]
    quads = [r for r in desc if rc[r] == 4]
    trips = [r for r in desc if rc[r] == 3]
    pairs = [r for r in desc if rc[r] == 2]
    if quads:
        q = quads[0]
        return (7, q, next(r for r in desc if r != q)) if len(desc) > 1 else (7, q)
    if trips and (len(trips) > 1 or pairs):
        p = max(trips[1:2] + pairs[:1])
        return (6, trips[0], p)
    if flush:
        return (5, *flush[:5])
    st = _straight_high(set(desc))
    if st >= 0:
        return (4, st)
    if trips:
        t = trips[0]
        return (3, t, *[r for r in desc if r != t][:2])
    if len(pairs) >= 2:
        p1, p2 = pairs[0], pairs[1]
        return (2, p1, p2, *[r for r in desc if r != p1 and r != p2][:1])
    if pairs:
        p = pairs[0]
        return (1, p, *[r for r in desc if r != p][:3])
    return (0, *desc[:5])

def _draws(hole, board):
    """-> (flush_draw, open_ended) using at least one hole card."""
    cards = hole + board
    fd = False
    for s in range(4):
        if sum(1 for c in cards if c & 3 == s) == 4 and any(c & 3 == s for c in hole):
            fd = True
    ranks = {c >> 2 for c in cards}
    if 12 in ranks:
        ranks.add(-1)  # ace low
    hole_ranks = {c >> 2 for c in hole} | ({-1} if any(c >> 2 == 12 for c in hole) else set())
    oe = False
    for lo in range(-1, 9):
        run = {lo, lo + 1, lo + 2, lo + 3}
        if run <= ranks and run & hole_ranks and lo - 1 >= -1 and lo + 4 <= 12:
            oe = True
    return fd, oe

def classify_hand(hole, board, good_kicker_rank=8):
    """Postflop hand -> bucket name. Fast (~2 hand_rank calls)."""
    mine = hand_rank(hole + board)
    on_board = hand_rank(board)
    cat = mine[0]
    board_ranks = sorted({c >> 2 for c in board}, reverse=True)
    h1, h2 = sorted((c >> 2 for c in hole), reverse=True)
    pocket_pair = h1 == h2
    river = len(board) >= 5
    fd, oe = (False, False) if river else _draws(hole, board)

    if mine == on_board:  # board plays
        made = WEAK
    elif cat >= 4:
        made = MONSTER if cat > on_board[0] else MEDIUM
    elif cat == 3:
        t = mine[1]
        if pocket_pair and h1 == t:
            made = MONSTER                     # set
        elif on_board[0] == 3:
            made = MEDIUM if max(h1, h2) >= 10 else WEAK  # trips on board, kicker matters
        else:
            made = STRONG                      # trips using one hole card
    elif cat == 2:
        p1, p2 = mine[1], mine[2]
        board_pairs = {r for r in board_ranks if sum(1 for c in board if c >> 2 == r) >= 2}
        if not ({p1, p2} & board_pairs):
            made = MONSTER                     # both pairs use hole cards
        else:
            hole_pair = p1 if p1 not in board_pairs else p2
            made = _one_pair_bucket(hole_pair, h1, h2, pocket_pair, board_ranks, good_kicker_rank) \
                if hole_pair not in board_pairs else (MEDIUM if h1 >= 11 else WEAK)
    elif cat == 1 and on_board[0] < 1:
        made = _one_pair_bucket(mine[1], h1, h2, pocket_pair, board_ranks, good_kicker_rank)
    else:
        made = WEAK

    if made in (WEAK, MEDIUM) and (fd and oe or (made == MEDIUM and fd)):
        return STRONG_DRAW
    if made == WEAK and (fd or oe):
        return DRAW
    return made

def _one_pair_bucket(p, h1, h2, pocket_pair, board_ranks, good_kicker_rank):
    if pocket_pair:
        if p > board_ranks[0]:
            return STRONG                      # overpair
        return MEDIUM if len(board_ranks) > 1 and p > board_ranks[1] else WEAK
    if p == board_ranks[0]:
        kicker = h2 if h1 == p else h1
        return STRONG if kicker >= good_kicker_rank or p == 12 and kicker >= good_kicker_rank - 2 else MEDIUM
    if len(board_ranks) > 1 and p == board_ranks[1]:
        return MEDIUM
    return WEAK

# ---- bot.py ----
STREETS = ("preflop", "flop", "turn", "river")

AGGRESSIVE = ("bet", "raise", "allin")

@dataclass
class PlayerInfo:
    seat: int
    stack: int              # chips behind (not counting bet this street)
    bet: int = 0            # chips put in on the current street
    active: bool = True     # still in the hand (not folded)
    all_in: bool = False
    dealt: bool = True      # False for busted / empty seats

@dataclass
class Action:
    kind: str               # "fold" | "check" | "call" | "bet" | "raise" | "allin"
    amount: int = 0         # for bet/raise: TOTAL street bet ("raise to"), like Exhibit B's "R"

@dataclass
class GameState:
    my_seat: int
    hole_cards: list        # ints (see poker_core.parse_cards)
    board: list
    street: str             # "preflop" | "flop" | "turn" | "river"
    pot: int                # all chips in the middle incl. this street's bets
    players: list           # PlayerInfo for every seat, indexed by seat
    button_seat: int
    small_blind: int
    big_blind: int
    to_call: int
    min_raise_to: int
    max_raise_to: int       # our stack + our current street bet
    # (street, seat, kind, amount) -- amount = that player's street total after acting
    history: list = field(default_factory=list)
    hand_number: int = 0
    legal_actions: tuple = ()  # optional; empty = assume standard NLHE legality

    @property
    def me(self):
        return self.players[self.my_seat]

class OpponentStats:
    def __init__(self):
        self.hands = {}
        self.vpip = {}
        self.pfr = {}

    def observe(self, history, seats):
        for s in seats:
            self.hands[s] = self.hands.get(s, 0) + 1
        vp, pr = set(), set()
        for street, seat, kind, _ in history:
            if street != "preflop":
                continue
            if kind in ("call",) + AGGRESSIVE:
                vp.add(seat)
            if kind in AGGRESSIVE:
                pr.add(seat)
        for s in vp:
            self.vpip[s] = self.vpip.get(s, 0) + 1
        for s in pr:
            self.pfr[s] = self.pfr.get(s, 0) + 1

    def _rate(self, table, seat, cfg):
        n = self.hands.get(seat, 0)
        return None if n < cfg.MIN_HANDS_FOR_READS else table.get(seat, 0) / n

    def is_loose(self, seat, cfg):
        r = self._rate(self.vpip, seat, cfg)
        return r is not None and r > cfg.LOOSE_VPIP

    def is_aggro(self, seat, cfg):
        r = self._rate(self.pfr, seat, cfg)
        return r is not None and r > cfg.AGGRO_PFR

LATER_POSITION = {"UTG": "UTG1", "UTG1": "MP", "MP": "HJ", "HJ": "CO", "CO": "BTN",
                  "BTN": "BTN", "SB": "SB", "BB": "BB"}

class PokerBot:
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        # cfg can be the config module or any object with the same attributes;
        # overrides={"OPEN_SIZE_BB": {...}} lets the simulator test variants.
        values = {k: getattr(cfg, k) for k in dir(cfg) if k.isupper()}
        values.update(overrides or {})
        self.cfg = SimpleNamespace(**values)
        self.rng = random.Random(seed if seed is not None else self.cfg.RANDOM_SEED)
        self.stats = OpponentStats()
        self._compile_ranges()

    # Parse every range once, so a decision is only set lookups.
    def _compile_ranges(self):
        c = self.cfg
        pr = parse_range
        self.R = SimpleNamespace(
            open={k: pr(v) for k, v in c.OPEN_RANGE.items()},
            threebet={k: pr(v) for k, v in c.THREEBET_RANGE.items()},
            call_open={k: pr(v) for k, v in c.CALL_VS_OPEN_RANGE.items()},
            overlimp=pr(c.OVERLIMP_RANGE),
            sb_complete=pr(c.SB_COMPLETE_RANGE),
            fourbet=pr(c.FOURBET_RANGE),
            call_3bet=pr(c.CALL_VS_3BET_RANGE),
            jam_4bet=pr(c.JAM_VS_4BET_RANGE),
            call_4bet=pr(c.CALL_VS_4BET_RANGE),
            shove=sorted((bb, pr(v)) for bb, v in c.SHOVE_RANGE_BY_STACK.items()),
            call_shove=pr(c.CALL_SHOVE_RANGE),
            call_shove_bubble=pr(c.CALL_SHOVE_RANGE_BUBBLE),
        )
        self.good_kicker = "23456789TJQKA".index(c.TOP_PAIR_GOOD_KICKER)

    # ------------------------------------------------------------ public
    def act(self, s: GameState) -> Action:
        try:
            a = self._preflop(s) if s.street == "preflop" else self._postflop(s)
        except Exception:  # never crash: the engine would auto check/fold anyway
            a = Action("check") if s.to_call == 0 else Action("fold")
        return self._legalize(s, a)

    def on_hand_end(self, history, seats_dealt):
        if self.cfg.TRACK_OPPONENTS:
            self.stats.observe(history, seats_dealt)

    # ------------------------------------------------------------ helpers
    def position(self, s, seat=None):
        seat = s.my_seat if seat is None else seat
        dealt = [p.seat for p in s.players if p.dealt]
        n = len(dealt)
        i = dealt.index(s.button_seat) if s.button_seat in dealt else 0
        order = dealt[i:] + dealt[:i]          # BTN first, then SB, BB, ...
        if n == 2:
            return "BTN" if seat == order[0] else "BB"
        middle = ["UTG", "UTG1", "MP", "HJ", "CO"]
        k = n - 3
        mids = (["UTG"] * max(0, k - 5) + middle)[-k:] if k > 0 else []
        labels = ["BTN", "SB", "BB"] + mids
        return labels[order.index(seat)]

    def _preflop_context(self, s):
        high, raises, limpers, callers, last_raiser = s.big_blind, 0, 0, 0, None
        for street, seat, kind, amt in s.history:
            if street != "preflop":
                continue
            if kind in AGGRESSIVE and amt > high:
                raises, high, last_raiser, callers = raises + 1, amt, seat, 0
            elif kind in ("call", "allin"):
                if raises == 0:
                    limpers += 1
                else:
                    callers += 1
        return SimpleNamespace(raises=raises, high=high, limpers=limpers,
                               callers=callers, last_raiser=last_raiser)

    def _effective_stack(self, s):
        mine = s.me.stack + s.me.bet
        others = [p.stack + p.bet for p in s.players if p.active and p.seat != s.my_seat]
        return min(mine, max(others)) if others else mine

    def _players_left(self, s):
        return sum(1 for p in s.players if p.dealt)

    def _raise_to(self, s, amount):
        return Action("raise", int(amount))

    def _check_fold(self, s):
        return Action("check") if s.to_call == 0 else Action("fold")

    # ------------------------------------------------------------ preflop
    def _preflop(self, s):
        c, R = self.cfg, self.R
        hc = hand_class(*s.hole_cards)
        pos = self.position(s)
        bb = s.big_blind
        ctx = self._preflop_context(s)
        eff_bb = self._effective_stack(s) / bb

        # --- short stack: push / fold
        if eff_bb <= c.SHOVE_STACK_BB:
            if ctx.raises == 0:
                rng = next((r for limit, r in R.shove if eff_bb <= limit), R.shove[-1][1])
                if hc in rng:
                    return Action("allin")
                if pos == "BB" and s.to_call == 0:
                    return Action("check")
                return self._check_fold(s)
            bubble = self._players_left(s) <= c.BUBBLE_PLAYERS_LEFT
            return Action("allin") if hc in (R.call_shove_bubble if bubble else R.call_shove) \
                else self._check_fold(s)

        # --- facing a shove from someone: use call-shove ranges
        raiser = s.players[ctx.last_raiser] if ctx.last_raiser is not None else None
        if raiser is not None and raiser.all_in and s.to_call >= s.me.stack * 0.5:
            bubble = self._players_left(s) <= c.BUBBLE_PLAYERS_LEFT
            return Action("call") if hc in (R.call_shove_bubble if bubble else R.call_shove) \
                else self._check_fold(s)

        # --- unopened / limped
        if ctx.raises == 0:
            if hc in R.open.get(pos, frozenset()):
                size = c.OPEN_SIZE_BB.get(pos, c.OPEN_SIZE_BB["default"])
                return self._raise_to(s, (size + c.LIMPER_ADD_BB * ctx.limpers) * bb)
            if pos == "SB" and hc in R.sb_complete and eff_bb > c.SB_COMPLETE_MAX_STACK_BB:
                return Action("call")
            if s.to_call == 0:
                return Action("check")
            if ctx.limpers > 0 and hc in R.overlimp:
                return Action("call")
            return Action("fold")

        # --- facing one raise
        if ctx.raises == 1:
            look_pos = pos
            if (c.WIDEN_VS_AGGRO_OPENER and ctx.last_raiser is not None
                    and self.stats.is_aggro(ctx.last_raiser, c)):
                look_pos = LATER_POSITION.get(pos, pos)
            if hc in R.threebet.get(look_pos, frozenset()):
                mult = c.THREEBET_MULT_OOP if pos in ("SB", "BB") else c.THREEBET_MULT_IP
                return self._raise_to(s, ctx.high * (mult + c.COLD_CALLER_ADD_MULT * ctx.callers))
            if hc in R.call_open.get(look_pos, frozenset()):
                return Action("call")
            return self._check_fold(s)

        # --- facing 3-bet
        if ctx.raises == 2:
            if hc in R.fourbet:
                return self._raise_to(s, ctx.high * c.FOURBET_MULT)
            if hc in R.call_3bet:
                return Action("call")
            return self._check_fold(s)

        # --- facing 4-bet+
        if hc in R.jam_4bet:
            return Action("allin")
        if hc in R.call_4bet:
            return Action("call")
        return self._check_fold(s)

    # ------------------------------------------------------------ postflop
    def _postflop(self, s):
        c = self.cfg
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        pol = c.POSTFLOP_POLICY[bucket]
        opponents = [p for p in s.players if p.active and p.seat != s.my_seat]
        multiway = len(opponents) >= 2
        strong_plus = bucket in (MONSTER, STRONG)
        pot = s.pot
        r = self.rng.random()

        # Low SPR: get it in with strong hands
        spr = s.me.stack / max(pot, 1)
        if strong_plus and spr <= c.COMMIT_SPR:
            return Action("allin")

        if s.to_call == 0:
            freq = pol["bet_freq"] * c.STREET_BET_FREQ_MULT.get(s.street, 1.0)
            if multiway and bucket != MONSTER:
                freq *= c.MULTIWAY_BET_FREQ_MULT
            size = pol["bet_size"]
            ctx = self._preflop_context(s)
            if (s.street == "flop" and ctx.last_raiser == s.my_seat
                    and not self._street_has_aggression(s)):
                cbet = c.CBET_FREQ_MULTIWAY if multiway else c.CBET_FREQ_HEADSUP
                if cbet > freq:
                    freq, size = cbet, c.CBET_SIZE
            if r < freq:
                return Action("bet", int(s.me.bet + size * pot))
            return Action("check")

        # Facing a bet
        price = s.to_call / (pot + s.to_call)
        allowed = pol["call_price"]
        if multiway and bucket != MONSTER:
            allowed *= c.MULTIWAY_CALL_PRICE_MULT
        allowed -= c.CALL_PRICE_PENALTY_PER_RAISE * max(0, self._street_raises(s) - 1)
        if any(self.stats.is_aggro(seat, c) or self.stats.is_loose(seat, c)
               for seat in self._street_aggressors(s)):
            allowed += c.CALL_PRICE_BONUS_VS_AGGRO

        if r < pol["raise_freq"]:
            high = s.me.bet + s.to_call
            return self._raise_to(s, high + pol["raise_size"] * (pot + s.to_call))
        if price <= allowed:
            return Action("call")
        invested = self._invested_this_hand(s)
        start_chips = invested + s.me.stack
        if (bucket in (MONSTER, STRONG, MEDIUM) and start_chips
                and invested / start_chips >= c.POT_COMMITTED_FRACTION and price <= 0.4):
            return Action("call")
        return Action("fold")

    def _street_has_aggression(self, s):
        return any(st == s.street and k in AGGRESSIVE for st, _, k, _ in s.history)

    def _street_raises(self, s):
        return sum(1 for st, _, k, _ in s.history if st == s.street and k in AGGRESSIVE)

    def _street_aggressors(self, s):
        return {seat for st, seat, k, _ in s.history if st == s.street and k in AGGRESSIVE}

    def _invested_this_hand(self, s):
        per_street = {}
        for st, seat, _, amt in s.history:
            if seat == s.my_seat:
                per_street[st] = max(per_street.get(st, 0), amt)
        per_street[s.street] = max(per_street.get(s.street, 0), s.me.bet)
        return sum(per_street.values())

    # ------------------------------------------------------------ legality
    def _legalize(self, s, a):
        me = s.me
        if a.kind == "fold":
            return Action("check") if s.to_call == 0 else a
        if a.kind == "check":
            return a if s.to_call == 0 else Action("fold")
        if a.kind == "call":
            if s.to_call == 0:
                return Action("check")
            return Action("allin") if s.to_call >= me.stack else a
        if a.kind == "allin":
            return Action("allin", s.max_raise_to)
        # bet / raise
        if s.min_raise_to >= s.max_raise_to:
            return Action("allin", s.max_raise_to)
        amt = max(int(a.amount), s.min_raise_to)
        if amt >= s.max_raise_to or amt >= self.cfg.JAM_IF_COMMIT_FRACTION * s.max_raise_to:
            return Action("allin", s.max_raise_to)
        street_high = me.bet + s.to_call
        return Action("bet" if street_high == 0 else "raise", amt)

# ---- bot_exploit.py ----
EXPLOIT_CONFIG = {
    # --- Bluff factor ---------------------------------------------------
    # Multiplies how often we bet or raise WITHOUT a made hand (the buckets
    # below), including c-bets with those hands. Frequencies cap at 100%.
    #   0.0 = never bluff   1.0 = same as PokerBot   2.0 = twice as often
    "BLUFF_FACTOR": 2.0,
    "BLUFF_BUCKETS": ("WEAK", "DRAW", "STRONG_DRAW"),

    # --- Tight-player read ------------------------------------------------
    # Plays (VPIP) fewer than this share of hands -> tight. Uses the existing
    # MIN_HANDS_FOR_READS from config.py before any read is made.
    "TIGHT_VPIP": 0.15,

    # --- Exploits vs tight players ---------------------------------------
    # 1) Steal more: when EVERY player still to act behind us is tight, open
    #    with the range of a position N seats later. From BTN/SB (nothing
    #    later) use STEAL_RANGE_VS_TIGHT instead.
    "STEAL_SHIFT_VS_TIGHT": 2,
    "STEAL_RANGE_VS_TIGHT": ("22+, A2s+, A2o+, K2s+, K5o+, Q2s+, Q8o+, J5s+, J8o+, T6s+, T8o+, "
                             "95s+, 97o+, 85s+, 87o, 74s+, 64s+, 53s+, 43s"),
    # 2) Respect their raises: vs a tight preflop raiser, use the 3-bet/call
    #    ranges of a position N seats EARLIER (tighter).
    "RESPECT_TIGHT_RAISES": True,
    "RESPECT_SHIFT_VS_TIGHT": 2,
    # 3) Bluff them more: extra multiplier on top of BLUFF_FACTOR when every
    #    opponent in the pot is tight, plus a bonus to c-bet frequency.
    "BLUFF_MULT_VS_TIGHT": 1.75,
    "CBET_BONUS_VS_TIGHT": 0.20,
    # 4) Fold more to their bets: their call_price is multiplied by this.
    "CALL_PRICE_MULT_VS_TIGHT": 0.75,
    # 5) Bet thin value less: they don't call with worse. MEDIUM bet_freq x this.
    "THIN_VALUE_MULT_VS_TIGHT": 0.7,

    # --- Trapping (slow-playing) -------------------------------------------
    # Checked to with a trap hand: check instead of betting this often.
    # A number (e.g. 0.3) applies to every street; a dict sets each street.
    # MONSTER defaults reproduce PokerBot's built-in slow-play rates exactly.
    "TRAP_FREQ": {"flop": 0.05, "turn": 0.145, "river": 0.24},          # MONSTER hands
    # STRONG hands (overpair, top pair good kicker, trips). None = don't trap,
    # bet them like PokerBot does. Try 0.2, or {"flop": 0.3, "turn": 0.2, "river": 0.1}.
    "TRAP_FREQ_STRONG": None,
    # We checked a trap hand earlier this street and now face a bet:
    # check-raise this often, otherwise just call.
    "CHECK_RAISE_FREQ": 0.85,          # MONSTER (PokerBot: 0.85)
    "CHECK_RAISE_FREQ_STRONG": 0.15,   # STRONG  (PokerBot: 0.15)
    # Trap streaks: how strongly this street's trap decision follows the last
    # street's (correlation, 0..1). 0 = independent coin flips (PokerBot).
    # After trapping the previous street, trap rate rises to
    #     f + rho * sqrt(f(1-f)) * sqrt((1-p)/p)
    # and after betting the previous street it drops to
    #     f - rho * sqrt(f(1-f)) * sqrt(p/(1-p))
    # (f = this street's TRAP_FREQ, p = last street's). The two balance, so the
    # average trap rate per street still equals TRAP_FREQ.
    # MONSTER defaults, rho = 0.1: turn 14.5% -> 29.9% after a flop trap (13.7% after a bet).
    # (River rates follow the same formula only if TRAP_ON_RIVER is True.)
    "TRAP_STREAK_CORRELATION": 0.1,
    # False = never trap on the river: MONSTER and STRONG hands always bet when
    # checked to, whatever happened on the flop and turn, whatever the river
    # entries in TRAP_FREQ / TRAP_FREQ_STRONG say, and even when
    # TRAP_FREQ_STRONG is None (PokerBot would check STRONG ~32% on the river).
    "TRAP_ON_RIVER": False,
}

EARLIER_POSITION = {"UTG": "UTG", "UTG1": "UTG", "MP": "UTG1", "HJ": "MP", "CO": "HJ",
                    "BTN": "CO", "SB": "HJ", "BB": "HJ"}

PREFLOP_ORDER = ["UTG", "UTG1", "MP", "HJ", "CO", "BTN", "SB", "BB"]

def _shift(pos, n, table):
    for _ in range(n):
        pos = table.get(pos, pos)
    return pos

class TightAwareStats(OpponentStats):
    def is_tight(self, seat, cfg):
        r = self._rate(self.vpip, seat, cfg)
        return r is not None and r < cfg.TIGHT_VPIP

class ExploitBot(PokerBot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**EXPLOIT_CONFIG, **(overrides or {})}, seed)
        self.stats = TightAwareStats()
        self.steal_vs_tight = parse_range(self.cfg.STEAL_RANGE_VS_TIGHT)

    # ------------------------------------------------------------ NEW helpers
    def _all_tight(self, s, seats):
        seats = list(seats)
        return bool(seats) and all(self.stats.is_tight(x, self.cfg) for x in seats)

    def _players_behind(self, s):
        """Seats still to act after us preflop (dealt, not folded, not all-in)."""
        mine = PREFLOP_ORDER.index(self.position(s))
        return [p.seat for p in s.players
                if p.active and not p.all_in and p.seat != s.my_seat
                and PREFLOP_ORDER.index(self.position(s, p.seat)) > mine]

    def _base_trap_freq(self, bucket, street):
        """Configured trap rate for this bucket and street, or None if it doesn't trap."""
        tf = (self.cfg.TRAP_FREQ if bucket == MONSTER
              else self.cfg.TRAP_FREQ_STRONG if bucket == STRONG else None)
        if tf is None:
            return None
        return tf.get(street, 0.0) if isinstance(tf, dict) else tf

    def _trap_freq(self, s, bucket):
        """Trap rate now, raised after trapping last street and lowered after betting it."""
        if bucket in (MONSTER, STRONG) and s.street == "river" and not self.cfg.TRAP_ON_RIVER:
            return 0.0                   # never trap the river (even if TRAP_FREQ_STRONG is None)
        f = self._base_trap_freq(bucket, s.street)
        rho = self.cfg.TRAP_STREAK_CORRELATION
        prev = {"turn": "flop", "river": "turn"}.get(s.street)
        if f is None or not prev or not rho or not 0 < f < 1:
            return f
        prev_board = s.board[:3 if prev == "flop" else 4]
        p = self._base_trap_freq(classify_hand(s.hole_cards, prev_board, self.good_kicker), prev)
        if p is None or not 0 < p < 1:
            return f                     # last street's hand wasn't a trap hand
        mine = [k for st, seat, k, _ in s.history if st == prev and seat == s.my_seat]
        if mine and mine[0] == "check" and not any(k in AGGRESSIVE for k in mine):
            f += rho * (f * (1 - f)) ** 0.5 * ((1 - p) / p) ** 0.5      # trapped last street
        elif mine and mine[0] == "bet":
            f -= rho * (f * (1 - f)) ** 0.5 * (p / (1 - p)) ** 0.5      # bet last street
        return min(1.0, max(0.0, f))

    def _bluff_mult(self, s, bucket, opponents):
        if bucket not in self.cfg.BLUFF_BUCKETS:
            return 1.0
        m = self.cfg.BLUFF_FACTOR
        if self._all_tight(s, (p.seat for p in opponents)):
            m *= self.cfg.BLUFF_MULT_VS_TIGHT
        return m

    # ------------------------------------------------------------ preflop
    # Copied from PokerBot._preflop; changes marked NEW.
    def _preflop(self, s):
        c, R = self.cfg, self.R
        hc = hand_class(*s.hole_cards)
        pos = self.position(s)
        bb = s.big_blind
        ctx = self._preflop_context(s)
        eff_bb = self._effective_stack(s) / bb

        # --- short stack: push / fold
        if eff_bb <= c.SHOVE_STACK_BB:
            if ctx.raises == 0:
                rng = next((r for limit, r in R.shove if eff_bb <= limit), R.shove[-1][1])
                if hc in rng:
                    return Action("allin")
                if pos == "BB" and s.to_call == 0:
                    return Action("check")
                return self._check_fold(s)
            bubble = self._players_left(s) <= c.BUBBLE_PLAYERS_LEFT
            return Action("allin") if hc in (R.call_shove_bubble if bubble else R.call_shove) \
                else self._check_fold(s)

        # --- facing a shove from someone: use call-shove ranges
        raiser = s.players[ctx.last_raiser] if ctx.last_raiser is not None else None
        if raiser is not None and raiser.all_in and s.to_call >= s.me.stack * 0.5:
            bubble = self._players_left(s) <= c.BUBBLE_PLAYERS_LEFT
            return Action("call") if hc in (R.call_shove_bubble if bubble else R.call_shove) \
                else self._check_fold(s)

        # --- unopened / limped
        if ctx.raises == 0:
            open_rng = R.open.get(pos, frozenset())
            # NEW: steal wider when everyone left to act is tight
            if ctx.limpers == 0 and pos != "BB" and self._all_tight(s, self._players_behind(s)):
                if pos in ("BTN", "SB"):
                    open_rng = self.steal_vs_tight
                else:
                    open_rng = R.open.get(_shift(pos, c.STEAL_SHIFT_VS_TIGHT, LATER_POSITION), open_rng)
            if hc in open_rng:
                size = c.OPEN_SIZE_BB.get(pos, c.OPEN_SIZE_BB["default"])
                return self._raise_to(s, (size + c.LIMPER_ADD_BB * ctx.limpers) * bb)
            if pos == "SB" and hc in R.sb_complete and eff_bb > c.SB_COMPLETE_MAX_STACK_BB:
                return Action("call")
            if s.to_call == 0:
                return Action("check")
            if ctx.limpers > 0 and hc in R.overlimp:
                return Action("call")
            return Action("fold")

        # --- facing one raise
        if ctx.raises == 1:
            look_pos = pos
            if (c.WIDEN_VS_AGGRO_OPENER and ctx.last_raiser is not None
                    and self.stats.is_aggro(ctx.last_raiser, c)):
                look_pos = LATER_POSITION.get(pos, pos)
            # NEW: tighten up against a tight raiser
            elif (c.RESPECT_TIGHT_RAISES and ctx.last_raiser is not None
                    and self.stats.is_tight(ctx.last_raiser, c)):
                look_pos = _shift(pos, c.RESPECT_SHIFT_VS_TIGHT, EARLIER_POSITION)
            if hc in R.threebet.get(look_pos, frozenset()):
                mult = c.THREEBET_MULT_OOP if pos in ("SB", "BB") else c.THREEBET_MULT_IP
                return self._raise_to(s, ctx.high * (mult + c.COLD_CALLER_ADD_MULT * ctx.callers))
            if hc in R.call_open.get(look_pos, frozenset()):
                return Action("call")
            return self._check_fold(s)

        # --- facing 3-bet
        if ctx.raises == 2:
            if hc in R.fourbet:
                return self._raise_to(s, ctx.high * c.FOURBET_MULT)
            if hc in R.call_3bet:
                return Action("call")
            return self._check_fold(s)

        # --- facing 4-bet+
        if hc in R.jam_4bet:
            return Action("allin")
        if hc in R.call_4bet:
            return Action("call")
        return self._check_fold(s)

    # ------------------------------------------------------------ postflop
    # Copied from PokerBot._postflop; changes marked NEW.
    def _postflop(self, s):
        c = self.cfg
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        pol = c.POSTFLOP_POLICY[bucket]
        opponents = [p for p in s.players if p.active and p.seat != s.my_seat]
        multiway = len(opponents) >= 2
        strong_plus = bucket in (MONSTER, STRONG)
        pot = s.pot
        r = self.rng.random()
        bluff_mult = self._bluff_mult(s, bucket, opponents)                    # NEW
        vs_tight = self._all_tight(s, (p.seat for p in opponents))            # NEW

        # Low SPR: get it in with strong hands
        spr = s.me.stack / max(pot, 1)
        if strong_plus and spr <= c.COMMIT_SPR:
            return Action("allin")

        if s.to_call == 0:
            tf = self._trap_freq(s, bucket)                                    # NEW: trap
            if tf is not None:
                if r >= 1.0 - tf:
                    return Action("check")
                return Action("bet", int(s.me.bet + pol["bet_size"] * pot))
            freq = pol["bet_freq"] * c.STREET_BET_FREQ_MULT.get(s.street, 1.0)
            if multiway and bucket != MONSTER:
                freq *= c.MULTIWAY_BET_FREQ_MULT
            freq *= bluff_mult                                                 # NEW
            if bucket == MEDIUM and vs_tight:                                  # NEW
                freq *= c.THIN_VALUE_MULT_VS_TIGHT
            size = pol["bet_size"]
            ctx = self._preflop_context(s)
            if (s.street == "flop" and ctx.last_raiser == s.my_seat
                    and not self._street_has_aggression(s)):
                cbet = c.CBET_FREQ_MULTIWAY if multiway else c.CBET_FREQ_HEADSUP
                cbet *= bluff_mult                                             # NEW
                if vs_tight:                                                   # NEW
                    cbet += c.CBET_BONUS_VS_TIGHT
                if cbet > freq:
                    freq, size = cbet, c.CBET_SIZE
            if r < min(freq, 1.0):                                             # NEW: cap
                return Action("bet", int(s.me.bet + size * pot))
            return Action("check")

        # Facing a bet
        price = s.to_call / (pot + s.to_call)
        allowed = pol["call_price"]
        if multiway and bucket != MONSTER:
            allowed *= c.MULTIWAY_CALL_PRICE_MULT
        allowed -= c.CALL_PRICE_PENALTY_PER_RAISE * max(0, self._street_raises(s) - 1)
        aggressors = self._street_aggressors(s)
        if any(self.stats.is_aggro(seat, c) or self.stats.is_loose(seat, c)
               for seat in aggressors):
            allowed += c.CALL_PRICE_BONUS_VS_AGGRO
        if any(self.stats.is_tight(seat, c) for seat in aggressors):           # NEW
            allowed *= c.CALL_PRICE_MULT_VS_TIGHT

        raise_freq = pol["raise_freq"] * bluff_mult                            # NEW: bluff factor
        if self._base_trap_freq(bucket, s.street) is not None and any(        # NEW: check-raise
                st == s.street and seat == s.my_seat and k == "check" for st, seat, k, _ in s.history):
            raise_freq = c.CHECK_RAISE_FREQ if bucket == MONSTER else c.CHECK_RAISE_FREQ_STRONG
        if r < min(raise_freq, 1.0):
            high = s.me.bet + s.to_call
            return self._raise_to(s, high + pol["raise_size"] * (pot + s.to_call))
        if price <= allowed:
            return Action("call")
        invested = self._invested_this_hand(s)
        start_chips = invested + s.me.stack
        if (bucket in (MONSTER, STRONG, MEDIUM) and start_chips
                and invested / start_chips >= c.POT_COMMITTED_FRACTION and price <= 0.4):
            return Action("call")
        return Action("fold")

