# ---- deep_thought_v2.py ----
DEEP2_CONFIG = {
    # --- stack-off limits: chips a hand may have in after betting or raising ----
    # The smaller of big blinds and share of the effective stack applies.
    "STACK_OFF_BB": {"STRONG": 40, "STRONG_DRAW": 25, "MEDIUM": 20, "DRAW": 15, "WEAK": 12},
    "STACK_OFF_SHARE": {"STRONG": 1.0, "STRONG_DRAW": 0.6, "MEDIUM": 0.5, "DRAW": 0.35, "WEAK": 0.25},
    # --- planning ---------------------------------------------------------------
    "PLAN_MIN_EQUITY": 0.8,         # V1 used 0.6, which stacked off with one pair
    "PLAN_MAX_SPR": 6,              # above this, three bets are too big a plan
    # --- all-ins ----------------------------------------------------------------
    "JAM_LEFTOVER": 0.2,            # jam if less than this share of the pot would be left behind
    "MULTIWAY_CALL_SHOVE": "TT+, AQs+, AQo+",
    "DRY_SIDE_POT_EQUITY": 0.85,    # bet into an empty side pot only with this much equity
}

class DeepThoughtV2Bot(DeepThoughtV1Bot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**DEEP2_CONFIG, **(overrides or {})}, seed)
        self.multiway_call_shove = parse_range(self.cfg.MULTIWAY_CALL_SHOVE)
        self.street = "flop"

    # ------------------------------------------------------------ chip helpers
    @staticmethod
    def _invested(s, seat):
        """Chips this seat has put in over the whole hand."""
        street_max = {}
        for st, who, kind, amt in s.history:
            if who == seat and kind not in ("check", "fold"):
                street_max[st] = max(street_max.get(st, 0), amt)
        return sum(street_max.values())

    def _spare_behind(self, s):
        """Chips we can actually lose: more than the biggest opposing stack can't be called."""
        others = [p.stack + p.bet for p in s.players if p.active and p.seat != s.my_seat and not p.all_in]
        return min(s.me.stack, max(0, max(others) - s.me.bet)) if others else 0

    def _stack_off_limit(self, s, bucket):
        c = self.cfg
        if bucket not in c.STACK_OFF_BB:
            return float("inf")
        behind_start = self._invested(s, s.my_seat) + self._spare_behind(s)
        return min(c.STACK_OFF_BB[bucket] * s.big_blind, c.STACK_OFF_SHARE[bucket] * behind_start)

    def _dry_side_pot(self, s):
        """True when an opponent is all-in, others remain, and no chips are in a side pot."""
        shoved = [p for p in s.players if p.active and p.all_in and p.seat != s.my_seat]
        live = [p for p in s.players if p.active and not p.all_in and p.seat != s.my_seat]
        if not shoved or not live:
            return False
        cap = max(self._invested(s, p.seat) for p in shoved)
        return all(self._invested(s, p.seat) <= cap for p in s.players if p.active)

    # ------------------------------------------------------------ EV helpers
    def _response(self, seat, bucket, frac):
        """(fold, call, raise) for this street, read between the fitted sizes."""
        c = self.cfg
        row = FIT_RESPONSE_V2[self.street][bucket]
        i = bisect_right(SIZE_POINTS, frac)
        if i == 0:
            mix = row[0]
        elif i == len(SIZE_POINTS):
            mix = row[-1]
        else:
            t = (frac - SIZE_POINTS[i - 1]) / (SIZE_POINTS[i] - SIZE_POINTS[i - 1])
            mix = [a + t * (b - a) for a, b in zip(row[i - 1], row[i])]
        read = self.sd.fold_rate(seat, c) / c.FOLD_PRIOR
        fold = min(0.95, mix[0] * min(1.5, max(0.5, read)))
        rest = (1 - fold) / max(1e-9, mix[1] + mix[2])
        return fold, mix[1] * rest, mix[2] * rest

    def _sizes(self, s, eq):
        """Pot fractions to try: within the stack-off limit and what they can call."""
        c = self.cfg
        spare = self._spare_behind(s)
        fractions = list(c.BET_SIZES)
        streets_left = {"flop": 3, "turn": 2, "river": 1}[s.street]
        if c.PLANNING and eq >= c.PLAN_MIN_EQUITY and 0 < spare <= c.PLAN_MAX_SPR * s.pot:
            fractions.append((((s.pot + 2 * spare) / s.pot) ** (1 / streets_left) - 1) / 2)
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        room = self._stack_off_limit(s, bucket) - self._invested(s, s.my_seat)
        return [f for f in fractions if f * s.pot <= room and (f * s.pot <= spare or spare == 0)] \
            or ([spare / s.pot] if 0 < spare <= room else [])

    # ------------------------------------------------------------ decisions
    def _preflop(self, s):
        a = super()._preflop(s)
        if a.kind not in ("call", "allin") or s.to_call == 0:
            return a
        ctx = self._preflop_context(s)
        raiser = s.players[ctx.last_raiser] if ctx.last_raiser is not None else None
        others = [p for p in s.players if p.active and p.seat != s.my_seat]
        if raiser is not None and raiser.all_in and ctx.raises >= 2 and len(others) >= 2 \
                and hand_class(*s.hole_cards) not in self.multiway_call_shove:
            return Action("fold")
        return a

    def _postflop(self, s):
        c = self.cfg
        self.street = s.street
        a = super()._postflop(s)
        if a.kind not in ("bet", "raise", "allin"):
            return a
        ev = self.last_ev or {}
        if self._dry_side_pot(s) and s.to_call == 0 and ev.get("equity", 0) < c.DRY_SIDE_POT_EQUITY:
            return Action("check")
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        cost = s.me.stack if a.kind == "allin" else a.amount - s.me.bet
        if self._invested(s, s.my_seat) + cost <= self._stack_off_limit(s, bucket):
            return a
        if s.to_call == 0:
            return Action("check")
        be = ev.get("breakeven")
        return Action("call") if be is None or ev.get("equity", 0) >= be else Action("fold")

    def _legalize(self, s, a):
        if s.street == "preflop" or a.kind not in ("bet", "raise"):
            return super()._legalize(s, a)
        amt = max(int(a.amount), s.min_raise_to)
        cost = amt - s.me.bet
        left = s.me.stack - cost
        spare = self._spare_behind(s)
        if s.min_raise_to >= s.max_raise_to or amt >= s.max_raise_to or left <= 0 \
                or (spare > 0 and spare - cost <= self.cfg.JAM_LEFTOVER * (s.pot + 2 * cost)):
            return Action("allin", s.max_raise_to)
        return Action("bet" if s.me.bet + s.to_call == 0 else "raise", amt)

# ---- deep_thought_v3.py ----
DEEP3_CONFIG = {
    # --- min-raise check-raise bluffs ---------------------------------------------
    "CHECK_RAISE_BLUFF": True,
    "CR_BUCKETS": ("WEAK", "DRAW"),
    "CR_FOLD_SCALE": 0.7,           # they fold less to a small raise than to a bet of that size
    "CR_MAX_SHARE": 0.6,            # at most this share of the effective stack in the pot
    # where it tested positive, measured bluff by bluff; turns and rivers lost chips
    "CR_STREETS": ("flop",),
    "CR_MIN_EFF_BB": 12,
    "CR_POSITIVE_BB": ((12, 20), (25, 50)),     # other depths above the minimum need a read first
    # bluff rate: starts reduced, reaches full as we see how this opponent reacts to raises
    "CR_BASE_FREQUENCY": 0.25,
    "CR_FULL_FREQUENCY": 0.5,
    "CR_READ_HANDS": 8,             # raises seen before the read has its full effect
    "CR_FOLD_PRIOR": 0.55,          # assumed fold-to-raise rate before any data
    "CR_FOLD_PRIOR_WEIGHT": 4,
    "CR_MIN_FOLD_RATE": 0.45,       # below this, stop bluffing them
}

class FoldToRaiseStats:
    """How often each opponent folds to a postflop raise, from every raise they face."""

    def __init__(self):
        self.folds = {}
        self.chances = {}

    def observe(self, history):
        for street in ("flop", "turn", "river"):
            high, raiser, responded = 0, None, set()
            for st, seat, kind, amt in history:
                if st != street:
                    continue
                if kind in AGGRESSIVE and amt > high:
                    if high > 0:
                        raiser, responded = seat, set()
                    high = amt
                elif raiser is not None and seat != raiser and seat not in responded:
                    responded.add(seat)
                    self.chances[seat] = self.chances.get(seat, 0) + 1
                    if kind == "fold":
                        self.folds[seat] = self.folds.get(seat, 0) + 1

    def seen(self, seat):
        return self.chances.get(seat, 0)

    def rate(self, seat, cfg):
        w = cfg.CR_FOLD_PRIOR_WEIGHT
        return (self.folds.get(seat, 0) + cfg.CR_FOLD_PRIOR * w) / (self.seen(seat) + w)

class DeepThoughtV3Bot(DeepThoughtV2Bot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**DEEP3_CONFIG, **(overrides or {})}, seed)
        self.last_hands = []
        self.raise_reads = FoldToRaiseStats()

    def on_hand_end(self, history, seats_dealt, showdown=None, board=None, my_seat=None):
        super().on_hand_end(history, seats_dealt, showdown=showdown, board=board, my_seat=my_seat)
        self.raise_reads.observe(history)

    def _hand_equities(self, s, hands):
        self.last_hands = super()._hand_equities(s, hands)
        return self.last_hands

    def _bluff_frequency(self, seat, effective_bb):
        """Reduced until we have a read, higher against folders, zero against callers."""
        c = self.cfg
        if self.raise_reads.rate(seat, c) < c.CR_MIN_FOLD_RATE:
            return 0.0
        positive = any(low < effective_bb <= high for low, high in c.CR_POSITIVE_BB)
        if not positive and self.raise_reads.seen(seat) < c.CR_READ_HANDS:
            return 0.0
        confidence = min(1.0, self.raise_reads.seen(seat) / c.CR_READ_HANDS)
        return c.CR_BASE_FREQUENCY + confidence * (c.CR_FULL_FREQUENCY - c.CR_BASE_FREQUENCY)

    def _check_raise_bluff(self, s, a):
        """Min-raise instead of `a` (a call or fold) when it is +EV as a bluff."""
        c = self.cfg
        opps = [p for p in s.players if p.active and p.seat != s.my_seat]
        checked = any(st == s.street and seat == s.my_seat and kind == "check" for st, seat, kind, _ in s.history)
        if not (c.CHECK_RAISE_BLUFF and s.street in c.CR_STREETS and checked and s.to_call
                and len(opps) == 1 and not opps[0].all_in
                and s.min_raise_to < s.max_raise_to
                and classify_hand(s.hole_cards, s.board, self.good_kicker) in c.CR_BUCKETS):
            return a
        cost = s.min_raise_to - s.me.bet
        spare = self._spare_behind(s)
        in_pot = self._invested(s, s.my_seat) + cost
        effective = self._invested(s, s.my_seat) + spare
        if cost >= spare or in_pot > c.CR_MAX_SHARE * effective \
                or effective / s.big_blind <= c.CR_MIN_EFF_BB:
            return a
        matched = s.to_call
        pot_after = s.pot + matched
        bet = cost - matched
        total = ev = 0.0
        for h in self.last_hands:
            fold, call, rais = self._response(opps[0].seat, h[3], bet / max(1, pot_after))
            read = self.raise_reads.rate(opps[0].seat, c) / c.CR_FOLD_PRIOR
            lost = fold * (1 - min(1.0, c.CR_FOLD_SCALE * read))     # folds that become calls
            fold, call = fold - lost, call + lost
            ev += h[2] * (fold * pot_after + call * (h[4] * (pot_after + 2 * bet) - bet) - rais * bet)
            total += h[2]
        ev = ev / total - matched if total else 0.0
        info = self.last_ev or {}
        call_ev = (info.get("equity", 0) * self._realize(s) - info.get("breakeven", 1)) * pot_after
        if ev > max(0.0, call_ev) and self.rng.random() < self._bluff_frequency(opps[0].seat, effective / s.big_blind):
            return Action("raise", s.min_raise_to)
        return a

    def _postflop(self, s):
        self.last_hands = []
        a = super()._postflop(s)
        return self._check_raise_bluff(s, a) if a.kind in ("call", "fold") else a

