TRACKERS = ("stats", "sd", "freq", "street_reads", "raise_reads", "lead_reads")

def tracker_counts(bot, seat):
    """Every count the trackers hold for `seat`: {tracker: {table: [[subkey, count], ...]}}."""
    out = {}
    for name in TRACKERS:
        for table, values in vars(getattr(bot, name)).items():
            if not isinstance(values, dict):
                continue
            rows = [[list(k[1:]) if isinstance(k, tuple) else [], v] for k, v in values.items()
                    if k == seat or (isinstance(k, tuple) and k[0] == seat)]
            if rows:
                out.setdefault(name, {})[table] = rows
    return out

def led_into(history, street, me):
    """The seat we would lead into: the last street's aggressor, if nobody has acted yet."""
    if any(st == street for st, _, _, _ in history):
        return None
    prev = ("preflop", "flop", "turn", "river")[("flop", "turn", "river").index(street)]
    seat = None
    for st, s, kind, _ in history:
        if st == prev and kind in AGGRESSIVE:
            seat = s
    return seat if seat is not None and seat != me else None

class LeadStats:
    """How each opponent answers when we lead into them."""

    def __init__(self):
        self.raises = {}
        self.chances = {}

    def observe(self, history, me):
        for street in ("flop", "turn", "river"):
            acts = [(i, seat, kind) for i, (st, seat, kind, _) in enumerate(history) if st == street]
            if not acts or acts[0][1] != me or acts[0][2] not in AGGRESSIVE:
                continue
            target = led_into(history[:acts[0][0]], street, me)
            reply = next((kind for _, seat, kind in acts[1:] if seat == target), None)
            if target is not None and reply is not None:
                self.chances[target] = self.chances.get(target, 0) + 1
                if reply in AGGRESSIVE:
                    self.raises[target] = self.raises.get(target, 0) + 1

    def raise_rate(self, seat, cfg):
        w = cfg.LEAD_RAISE_WEIGHT
        return (self.raises.get(seat, 0) + cfg.LEAD_RAISE_PRIOR * w) / (self.chances.get(seat, 0) + w)

class DeepThoughtV5Bot(DeepThoughtV4Bot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**DEEP5_CONFIG, **(overrides or {})}, seed)
        self.lead_reads = LeadStats()
        self.value_bets = {}        # (street, role) -> our non-weak bets
        self.weak_spots = {}        # (street, role) -> times we held a weak hand there

    def on_hand_end(self, history, seats_dealt, showdown=None, board=None, my_seat=None):
        super().on_hand_end(history, seats_dealt, showdown=showdown, board=board, my_seat=my_seat)
        self.lead_reads.observe(history, self._my_seat if my_seat is None else my_seat)

    def load_profile(self, seat, profile):
        """Start this seat's reads from a saved profile, scaled to PROFILE_MAX_HANDS."""
        scale = min(1.0, self.cfg.PROFILE_MAX_HANDS / max(1, profile.get("hands", 1)))
        for name, tables in profile.get("counts", {}).items():
            tracker = getattr(self, name, None)
            for table, rows in tables.items():
                values = getattr(tracker, table, None)
                if not isinstance(values, dict):
                    continue
                for sub, count in rows:
                    key = (seat, *sub) if sub else seat
                    values[key] = values.get(key, 0) + count * scale

    # ------------------------------------------------------------ bluff frequency
    def _role(self, s, opp):
        """'lead' into the last street's aggressor, 'aggressor' if that was us, else 'probe'."""
        if led_into(s.history, s.street, s.my_seat) == opp:
            return "lead"
        prev = ("preflop", "flop", "turn", "river")[("flop", "turn", "river").index(s.street)]
        last = None
        for st, seat, kind, _ in s.history:
            if st == prev and kind in AGGRESSIVE:
                last = seat
        return "aggressor" if last == s.my_seat else "probe"

    def _bluff_gate(self, s, a, opp, key):
        """Keep a weak bet with the balanced frequency for its size, moved by their fold rate."""
        c = self.cfg
        size = (s.me.stack if a.kind == "allin" else a.amount - s.me.bet) / max(1, s.pot)
        share = min(c.BLUFF_MAX_SHARE, size / (1 + 2 * size) * c.BLUFF_STREET_ROOM[s.street])
        w = c.BLUFF_VALUE_WEIGHT
        value = (self.value_bets.get(key, 0) + c.BLUFF_VALUE_PRIOR * w) / (self.weak_spots.get(key, 0) + w)
        chance = share / (1 - share) * value
        fold, even = self.sd.fold_rate(opp, c), size / (1 + size)
        low, high = c.BLUFF_MULT_RANGE
        mult = ((fold / (1 - fold)) / (even / (1 - even))) ** c.BLUFF_EXPLOIT_POWER
        chance *= min(high, max(low, mult))
        return a if self.rng.random() < chance else Action("check")

    def _lead(self, s, a):
        """Weak leads: check against opponents who raise leads, else keep the size in range."""
        c = self.cfg
        opps = [p for p in s.players if p.active and p.seat != s.my_seat]
        target = led_into(s.history, s.street, s.my_seat)
        if len(opps) != 1 or target != opps[0].seat or a.kind != "bet" \
                or classify_hand(s.hole_cards, s.board, self.good_kicker) not in c.LEAD_BUCKETS:
            return a
        if self.lead_reads.raise_rate(target, c) > c.LEAD_MAX_RAISE:
            return Action("check")
        if c.LEAD_SIZE_RANGE is None:
            return a
        low, high = c.LEAD_SIZE_RANGE
        bet = min(max(a.amount - s.me.bet, int(low * s.pot)), int(high * s.pot))
        return Action("bet", s.me.bet + bet)

    def _postflop(self, s):
        a = super()._postflop(s)
        opps = [p for p in s.players if p.active and p.seat != s.my_seat]
        if s.to_call or len(opps) != 1:
            return a
        if a.kind in AGGRESSIVE:
            a = self._lead(s, a)
        c = self.cfg
        if not c.BLUFF_CONTROL:
            return a
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        key = (s.street, self._role(s, opps[0].seat))
        # a weak hand ahead of their range is a thin value bet, not a bluff
        equity = (self.last_ev or {}).get("equity", 0)
        if bucket not in c.BLUFF_BUCKETS or equity >= c.BLUFF_MAX_EQUITY:
            if a.kind in AGGRESSIVE:
                self.value_bets[key] = self.value_bets.get(key, 0) + 1
            return a
        self.weak_spots[key] = self.weak_spots.get(key, 0) + 1
        return self._bluff_gate(s, a, opps[0].seat, key) if a.kind in AGGRESSIVE else a

# ---- deep_thought_v6.py ----
DEEP6_CONFIG = {
    # --- bluff reads by bet size ---------------------------------------------------
    "SIZE_READS": True,
    "BIG_BET_SIZE": 0.6,                # bets of at least this share of the pot are big
    "SIZE_BLUFF_WEIGHT": 6,             # the pooled bluff rate counts like this many bets
    # --- bluff reads by line, within each size ----------------------------------------
    "LINE_READS": True,
    "LINE_BLUFF_WEIGHT": 6,             # the size's bluff rate counts like this many bets
    # --- big 3-bets -------------------------------------------------------------------
    "BIG_3BET_READS": False,
    "BIG_3BET_VALUE_PRIOR": 0.5,        # value share of a big 3-bet at the reference 3-bet rate
    "BIG_3BET_VALUE_MAX": 0.9,
    "BIG_3BET_VALUE_WEIGHT": 4,         # the prior counts like this many shown hands
    "BIG_3BET_VALUE_RANGE": "88+, ATs+, KQs, AJo+, KQo",
    "TIGHT_VALUE_SHARE": 0.7,
    "HU_BTN_CALL_TIGHT_BIG_3BET": "TT-88, AQs-AJs, KQs, AQo",
}

TRACKERS_V6 = TRACKERS + ("big3",)

STREET_LEN = {"flop": 3, "turn": 4, "river": 5}

def tracker_counts(bot, seat):
    """Every count the trackers hold for `seat`: {tracker: {table: [[subkey, count], ...]}}."""
    out = {}
    for name in TRACKERS_V6:
        for table, values in vars(getattr(bot, name)).items():
            if not isinstance(values, dict):
                continue
            rows = [[list(k[1:]) if isinstance(k, tuple) else [], v] for k, v in values.items()
                    if k == seat or (isinstance(k, tuple) and k[0] == seat)]
            if rows:
                out.setdefault(name, {})[table] = rows
    return out

def bet_lines(history):
    """(street, seat, size, line) for every postflop bet or raise.

    size is the raise over the pot after calling. line is "raise" over a bet, "agg" by
    the last street's aggressor, "lead" into that aggressor before they act, or "free"
    (a bet after a check, or after a street with no bets)."""
    out, pot, last = [], 0, None
    for street in ("preflop", "flop", "turn", "river"):
        put, high, acted, agg = {}, 0, set(), None
        for st, seat, kind, amt in history:
            if st != street:
                continue
            if kind in AGGRESSIVE and amt > high:
                if street != "preflop":
                    call = high - put.get(seat, 0)
                    size = (amt - high) / max(1, pot + sum(put.values()) + call)
                    line = ("raise" if high else "agg" if seat == last
                            else "lead" if last is not None and not acted else "free")
                    out.append((street, seat, size, line))
                agg = seat
            if kind != "blind":
                acted.add(seat)
            if kind != "fold":
                put[seat] = max(put.get(seat, 0), amt)
            high = max(high, amt)
        pot += sum(put.values())
        last = agg
    return out

class SizedShowdownStats(ShowdownStats):
    """ShowdownStats that also splits shown bets by size and line, and judges a bet by both."""

    def __init__(self, big_size=0.6, weight=6, line_weight=6):
        super().__init__()
        self.sized_bets = {}      # (seat, river|early, small|big) -> bets shown
        self.sized_bluffs = {}    # ... of which were bluffs (weighted)
        self.line_bets = {}       # (seat, river|early, small|big, line) -> bets shown
        self.line_bluffs = {}
        self.big_size, self.weight, self.line_weight = big_size, weight, line_weight
        self.facing = None        # the size of the bet we face now, set by the bot
        self.facing_line = None   # ... and its line, None when line reads are off
        # Count bets whose cards we see without a showdown too. Replays show every hand,
        # so profiles see each bet, bluffs that won included; live play sees showdowns.
        self.see_all = False

    def _group(self, street, size):
        return ("river" if street == "river" else "early", "big" if size >= self.big_size else "small")

    def observe(self, history, showdown, board, good_kicker, me, semi_bluff_weight):
        super().observe(history, showdown, board, good_kicker, me, semi_bluff_weight)
        folded = {seat for _, seat, kind, _ in history if kind == "fold"}
        shown = dict(showdown or {})
        if not self.see_all:
            shown = {seat: cards for seat, cards in shown.items() if seat not in folded}
            if len(shown) < 2 or not board or len(board) < 5:
                return
        biggest = {}            # (street, seat) -> [largest size, line of their first bet]
        for street, seat, size, line in bet_lines(history):
            if seat in shown and seat != me and len(board or []) >= STREET_LEN[street]:
                top = biggest.setdefault((street, seat), [size, line])
                top[0] = max(top[0], size)
        for (street, seat), (size, line) in biggest.items():
            bucket = classify_hand(list(shown[seat]), list(board[:STREET_LEN[street]]), good_kicker)
            weight = BLUFF_WEIGHT.get(bucket, semi_bluff_weight if bucket == "STRONG_DRAW" else 0.0)
            key = (seat, *self._group(street, size))
            self.sized_bets[key] = self.sized_bets.get(key, 0) + 1
            self.sized_bluffs[key] = self.sized_bluffs.get(key, 0) + weight
            key += (line,)
            self.line_bets[key] = self.line_bets.get(key, 0) + 1
            self.line_bluffs[key] = self.line_bluffs.get(key, 0) + weight

    def bluff_rate(self, seat, cfg, street="flop"):
        pooled = super().bluff_rate(seat, cfg, street)
        if self.facing is None:
            return pooled
        key = (seat, *self._group(street, self.facing))
        w = self.weight
        sized = (self.sized_bluffs.get(key, 0) + pooled * w) / (self.sized_bets.get(key, 0) + w)
        if self.facing_line is None:
            return sized
        key += (self.facing_line,)
        w = self.line_weight
        return (self.line_bluffs.get(key, 0) + sized * w) / (self.line_bets.get(key, 0) + w)

class Big3BetStats:
    """Each opponent's big 3-bets over our open, and what they showed with them."""

    def __init__(self, mult=5.0, value_range=frozenset()):
        self.made = {}       # big 3-bets over our open
        self.shown = {}      # ... seen at showdown
        self.value = {}      # ... of which were in the value range
        self.mult, self.value_range = mult, value_range

    def observe(self, history, showdown, me):
        bb = max([amt for st, _, kind, amt in history if st == "preflop" and kind == "blind"] or [0])
        opens = [(seat, amt) for st, seat, kind, amt in history
                 if st == "preflop" and kind in AGGRESSIVE and amt > bb]
        if len(opens) < 2 or opens[0][0] != me or opens[1][0] == me or opens[1][1] <= opens[0][1] * self.mult:
            return
        seat = opens[1][0]
        self.made[seat] = self.made.get(seat, 0) + 1
        # any cards we are shown count: replays show every hand, live play only showdowns
        cards = (showdown or {}).get(seat)
        if cards:
            self.shown[seat] = self.shown.get(seat, 0) + 1
            if hand_class(*cards) in self.value_range:
                self.value[seat] = self.value.get(seat, 0) + 1

    def value_share(self, seat, freq_ratio, cfg):
        prior = min(cfg.BIG_3BET_VALUE_MAX, cfg.BIG_3BET_VALUE_PRIOR / max(0.01, freq_ratio))
        w = cfg.BIG_3BET_VALUE_WEIGHT
        return (self.value.get(seat, 0) + prior * w) / (self.shown.get(seat, 0) + w)

class DeepThoughtV6Bot(DeepThoughtV5Bot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**DEEP6_CONFIG, **(overrides or {})}, seed)
        c = self.cfg
        self.sd = SizedShowdownStats(c.BIG_BET_SIZE, c.SIZE_BLUFF_WEIGHT, c.LINE_BLUFF_WEIGHT)
        self.big3 = Big3BetStats(c.HU_3BET_TIGHT_MULT, parse_range(c.BIG_3BET_VALUE_RANGE))
        self.tight_big_3bet_call = parse_range(c.HU_BTN_CALL_TIGHT_BIG_3BET)

    def on_hand_end(self, history, seats_dealt, showdown=None, board=None, my_seat=None):
        super().on_hand_end(history, seats_dealt, showdown=showdown, board=board, my_seat=my_seat)
        self.big3.observe(history, showdown, self._my_seat if my_seat is None else my_seat)

    def _postflop(self, s):
        if self.cfg.SIZE_READS and s.to_call:
            self.sd.facing = s.to_call / max(1, s.pot - s.to_call)
            if self.cfg.LINE_READS:
                lines = [line for st, seat, _, line in bet_lines(s.history)
                         if st == s.street and seat != s.my_seat]
                self.sd.facing_line = lines[-1] if lines else None
        try:
            return super()._postflop(s)
        finally:
            self.sd.facing = self.sd.facing_line = None

    def _defend_3bet(self, s, hc, ctx):
        a = super()._defend_3bet(s, hc, ctx)
        c = self.cfg
        if not c.BIG_3BET_READS or a.kind != "call" or ctx.last_raiser is None:
            return a
        opens = [amt for st, _, kind, amt in s.history
                 if st == "preflop" and kind in AGGRESSIVE and amt > s.big_blind]
        if len(opens) < 2 or opens[-1] <= opens[0] * c.HU_3BET_TIGHT_MULT:
            return a
        ratio = self._freq_ratio(s, ctx.last_raiser, "three_bet")
        if self.big3.value_share(ctx.last_raiser, ratio, c) < c.TIGHT_VALUE_SHARE:
            return a
        return a if hc in self.tight_big_3bet_call else self._check_fold(s)

# ---- deep_thought_v7.py ----
DEEP7_CONFIG = {
    "EXPLOIT_Z": 1.0,                   # standard errors a read must clear before it acts
    "EXPLOIT_PROFILE_HANDS": 600,       # saved history these reads take, in hands
    # --- raises on our first flop bet (not leads, which v5 handles) ---------------------
    "CBET_RAISE_READS": True,
    "CBET_RAISE_PRIOR": 0.085,          # Chipzen field: 8.6% of continuation bets raised
    "CBET_RAISE_WEIGHT": 10,
    "CBET_MAX_RAISE": 0.15,             # weak hands check against bots confidently above this
    # --- turn barrels after a called flop bet -------------------------------------------
    "BARREL_READS": True,
    "BARREL_FOLD_PRIOR": 0.39,          # Chipzen field: folds to the turn bet after calling
    "BARREL_FOLD_WEIGHT": 8,
    "BARREL_SIZE": 0.5,                 # share of the pot for a barrel we add
    "BARREL_DRAW_CREDIT": 0.12,         # draws need this much less fold rate (outs pay back)
    # --- thin turn value bets against weak callers --------------------------------------
    "THIN_VALUE_READS": True,
    "CALL_WEAK_PRIOR": 0.53,            # Chipzen field: turn calls with weak hands or draws
    "CALL_WEAK_WEIGHT": 8,
    "THIN_VALUE_SHARE": 0.6,            # bet medium hands when their weak share is confidently above
    "THIN_VALUE_SIZE": 0.5,
    # --- weak hands fold to heavy bettors who fold -------------------------------------
    "FOLD_WEAK_VS_BARRELER": False,
    "BARRELER_RATIO": 1.3,              # first bets per chance vs the reference rate
    "BARRELER_MIN_FOLD": 0.45,          # their fold rate to our bets
    "BARRELER_MAX_BLUFF": 0.45,         # bluff share of the bets they have shown down
}

EXPLOIT_TRACKERS = ("cbet_raises", "barrels", "turn_calls")

TRACKERS_V7 = TRACKERS_V6 + EXPLOIT_TRACKERS

def tracker_counts(bot, seat):
    """Every count the trackers hold for `seat`: {tracker: {table: [[subkey, count], ...]}}."""
    out = {}
    for name in TRACKERS_V7:
        for table, values in vars(getattr(bot, name)).items():
            if not isinstance(values, dict):
                continue
            rows = [[list(k[1:]) if isinstance(k, tuple) else [], v] for k, v in values.items()
                    if k == seat or (isinstance(k, tuple) and k[0] == seat)]
            if rows:
                out.setdefault(name, {})[table] = rows
    return out

def read(hits, chances, prior, weight, z):
    """(estimate, low, high): the rate pulled toward `prior`, +- z standard errors."""
    est = (hits + prior * weight) / (chances + weight)
    err = z * math.sqrt(est * (1 - est) / (chances + weight))
    return est, est - err, est + err

def first_bet(history, street):
    """(seat, index) of the first bet on this street, or (None, None)."""
    acts = [(seat, kind) for st, seat, kind, _ in history if st == street]
    for i, (seat, kind) in enumerate(acts):
        if kind in AGGRESSIVE:
            return seat, i
    return None, None

def called_flop_bet(history, me):
    """The seat that called our first flop bet without raising, or None."""
    seat, i = first_bet(history, "flop")
    if seat is None or seat != me:
        return None
    acts = [(s, kind) for st, s, kind, _ in history if st == "flop"][i + 1:]
    if any(kind in AGGRESSIVE for _, kind in acts):
        return None
    return next((s for s, kind in acts if kind == "call"), None)

class CbetRaiseStats:
    """How often each opponent raises our first flop bet when it isn't a lead."""

    def __init__(self):
        self.raises = {}
        self.chances = {}

    def observe(self, history, me):
        seat, i = first_bet(history, "flop")
        if seat is None or seat != me:
            return
        line = next((l for st, s, _, l in bet_lines(history) if st == "flop" and s == me), None)
        if line == "lead":
            return
        acts = [(s, kind) for st, s, kind, _ in history if st == "flop"][i + 1:]
        reply = next(((s, kind) for s, kind in acts if s != me), None)
        if reply is not None:
            self.chances[reply[0]] = self.chances.get(reply[0], 0) + 1
            if reply[1] in AGGRESSIVE:
                self.raises[reply[0]] = self.raises.get(reply[0], 0) + 1

    def read(self, seat, cfg):
        return read(self.raises.get(seat, 0), self.chances.get(seat, 0),
                    cfg.CBET_RAISE_PRIOR, cfg.CBET_RAISE_WEIGHT, cfg.EXPLOIT_Z)

class BarrelStats:
    """How often each opponent folds to our turn bet after calling our flop bet."""

    def __init__(self):
        self.folds = {}
        self.chances = {}

    def observe(self, history, me):
        seat = called_flop_bet(history, me)
        bettor, i = first_bet(history, "turn")
        if seat is None or bettor is None or bettor != me:
            return
        acts = [(s, kind) for st, s, kind, _ in history if st == "turn"][i + 1:]
        reply = next((kind for s, kind in acts if s == seat), None)
        if reply is not None:
            self.chances[seat] = self.chances.get(seat, 0) + 1
            if reply == "fold":
                self.folds[seat] = self.folds.get(seat, 0) + 1

    def read(self, seat, cfg):
        return read(self.folds.get(seat, 0), self.chances.get(seat, 0),
                    cfg.BARREL_FOLD_PRIOR, cfg.BARREL_FOLD_WEIGHT, cfg.EXPLOIT_Z)

class TurnCallStats:
    """What each opponent holds when they call our turn bets: the share of weak hands and draws."""

    def __init__(self):
        self.calls = {}
        self.weak = {}
        self.see_all = False        # as SizedShowdownStats.see_all

    def observe(self, history, showdown, board, good_kicker, me):
        if not board or len(board) < 4:
            return
        folded = {seat for _, seat, kind, _ in history if kind == "fold"}
        high = 0
        for st, seat, kind, amt in history:
            if st != "turn":
                continue
            if kind == "call" and seat != me and high:
                cards = (showdown or {}).get(seat)
                if cards and (self.see_all or seat not in folded):
                    bucket = classify_hand(list(cards), list(board[:4]), good_kicker)
                    self.calls[seat] = self.calls.get(seat, 0) + 1
                    if bucket in ("WEAK", "DRAW"):
                        self.weak[seat] = self.weak.get(seat, 0) + 1
            if kind in AGGRESSIVE:
                high = max(high, amt)

    def read(self, seat, cfg):
        return read(self.weak.get(seat, 0), self.calls.get(seat, 0),
                    cfg.CALL_WEAK_PRIOR, cfg.CALL_WEAK_WEIGHT, cfg.EXPLOIT_Z)

class DeepThoughtV7Bot(DeepThoughtV6Bot):
    def __init__(self, cfg=default_config, overrides=None, seed=None):
        super().__init__(cfg, {**DEEP7_CONFIG, **(overrides or {})}, seed)
        self.cbet_raises = CbetRaiseStats()
        self.barrels = BarrelStats()
        self.turn_calls = TurnCallStats()
        self.forced = {}            # seat -> exploits a saved profile forces on

    def load_profile(self, seat, profile):
        """v6's profile load, with more history for the exploit reads and any forced exploits."""
        counts = profile.get("counts", {})
        super().load_profile(seat, {**profile, "counts": {k: v for k, v in counts.items()
                                                          if k not in EXPLOIT_TRACKERS}})
        scale = min(1.0, self.cfg.EXPLOIT_PROFILE_HANDS / max(1, profile.get("hands", 1)))
        for name in EXPLOIT_TRACKERS:
            tracker = getattr(self, name)
            for table, rows in counts.get(name, {}).items():
                values = getattr(tracker, table, None)
                if not isinstance(values, dict):
                    continue
                for sub, count in rows:
                    key = (seat, *sub) if sub else seat
                    values[key] = values.get(key, 0) + count * scale
        if profile.get("force"):
            self.forced[seat] = set(profile["force"])

    def position(self, s, seat=None):
        """Heads-up preflop, the small blind plays the button's ranges, whatever button_seat says.

        When a Chipzen 6-max table is down to two, dealer_seat points at the big blind, and
        the big blind does act last on every street after the flop (the small blind acts
        first all hand), so postflop keeps that reading. Preflop it made the small blind
        call itself "BB" and fold 22 and T6s at 15 BB. In 2-seat matches the small blind is
        the button anyway, so nothing changes there.
        """
        if s.street == "preflop" and sum(1 for p in s.players if p.dealt) == 2:
            blinds = [who for street, who, kind, _ in s.history if street == "preflop" and kind == "blind"]
            if len(blinds) == 2:
                seat = s.my_seat if seat is None else seat
                return "BTN" if seat == blinds[0] else "BB"
        return super().position(s, seat)

    def see_everything(self):
        """Count every hand whose cards we are given, not only showdowns (for replays)."""
        self.sd.see_all = self.turn_calls.see_all = True

    def on_hand_end(self, history, seats_dealt, showdown=None, board=None, my_seat=None):
        super().on_hand_end(history, seats_dealt, showdown=showdown, board=board, my_seat=my_seat)
        me = self._my_seat if my_seat is None else my_seat
        self.cbet_raises.observe(history, me)
        self.barrels.observe(history, me)
        self.turn_calls.observe(history, showdown, board, self.good_kicker, me)

    # ------------------------------------------------------------ exploits
    def _forced(self, opp, name):
        return name in self.forced.get(opp, ())

    def _checks_weak_flops(self, opp):
        c = self.cfg
        return c.CBET_RAISE_READS and (self._forced(opp, "check_weak_flops")
                                       or self.cbet_raises.read(opp, c)[1] > c.CBET_MAX_RAISE)

    def _barrel(self, opp, size, bucket):
        """+1 to add a turn barrel, -1 to drop one, 0 to leave it to v6."""
        c = self.cfg
        if not c.BARREL_READS:
            return 0
        if self._forced(opp, "barrel_" + bucket.lower()):
            return 1
        _, low, high = self.barrels.read(opp, c)
        even = size / (1 + size)
        # draws can barrel a bit below break-even, but only against bots that fold more
        # than the field: at the field's rate that choice is v6's, not an exploit
        if low >= even - (c.BARREL_DRAW_CREDIT if bucket == "DRAW" else 0) and low > c.BARREL_FOLD_PRIOR:
            return 1
        return -1 if bucket == "WEAK" and high < even else 0

    def _thin_value(self, opp):
        c = self.cfg
        return c.THIN_VALUE_READS and (self._forced(opp, "thin_value")
                                       or self.turn_calls.read(opp, c)[1] >= c.THIN_VALUE_SHARE)

    def exploit_plan(self, opp):
        """What v7 does differently against this opponent right now, in words."""
        c, plan = self.cfg, []
        if self.lead_reads.raise_rate(opp, c) > c.LEAD_MAX_RAISE:
            plan.append(f"checks weak leads (raises {self.lead_reads.raise_rate(opp, c):.0%} of leads)")
        est = self.cbet_raises.read(opp, c)[0]
        if self._checks_weak_flops(opp):
            plan.append(f"checks weak flops (raises {est:.0%} of flop bets)")
        est = self.barrels.read(opp, c)[0]
        for bucket, words in (("WEAK", "weak hands"), ("DRAW", "draws")):
            move = self._barrel(opp, c.BARREL_SIZE, bucket)
            if move:
                plan.append(f"{'barrels' if move > 0 else 'gives up'} the turn with {words} "
                            f"(folds {est:.0%} to a second bet"
                            + (", forced" if self._forced(opp, "barrel_" + bucket.lower()) else "") + ")")
        if self._thin_value(opp):
            plan.append(f"bets medium hands on the turn ({self.turn_calls.read(opp, c)[0]:.0%} of turn calls weak)")
        return plan

    def _bet(self, s, share):
        amount = s.me.bet + max(s.big_blind, int(share * s.pot))
        return Action("bet", max(s.min_raise_to, min(s.max_raise_to, amount)))

    def _barreler(self, s, opps):
        """The one opponent whose flop or turn bet we face, if it bets heavily and folds."""
        c = self.cfg
        if s.street not in ("flop", "turn") or len(opps) != 1 or self._facing_raise(s):
            return None
        agg = self._aggressor(s)
        if agg is None or self._freq_ratio(s, agg, "bet") < c.BARRELER_RATIO \
                or self.sd.fold_rate(agg, c) < c.BARRELER_MIN_FOLD \
                or self.sd.bluff_rate(agg, c, s.street) > c.BARRELER_MAX_BLUFF:
            return None
        return agg

    def _postflop(self, s):
        a = super()._postflop(s)
        opps = [p for p in s.players if p.active and p.seat != s.my_seat]
        if s.to_call and a.kind == "call" and self.cfg.FOLD_WEAK_VS_BARRELER \
                and classify_hand(s.hole_cards, s.board, self.good_kicker) == "WEAK" \
                and self._barreler(s, opps) is not None:
            return Action("fold")
        if s.to_call or len(opps) != 1 or s.street == "river":
            return a
        opp = opps[0].seat
        bucket = classify_hand(s.hole_cards, s.board, self.good_kicker)
        betting = a.kind in AGGRESSIVE
        if s.street == "flop":
            if betting and bucket == "WEAK" and led_into(s.history, s.street, s.my_seat) != opp \
                    and self._checks_weak_flops(opp):
                return Action("check")
            return a
        if called_flop_bet(s.history, s.my_seat) != opp:
            return a
        if bucket in ("WEAK", "DRAW"):
            size = (a.amount - s.me.bet) / max(1, s.pot) if a.kind == "bet" else self.cfg.BARREL_SIZE
            move = self._barrel(opp, size, bucket)
            if move > 0 and not betting:
                return self._bet(s, self.cfg.BARREL_SIZE)
            if move < 0 and betting:
                return Action("check")
            return a
        if bucket == "MEDIUM" and not betting and self._thin_value(opp):
            return self._bet(s, self.cfg.THIN_VALUE_SIZE)
        return a

